// The corpus importer (packages/db parser) writes "(missing — placeholder generated by importer)"
// where an old BITS Word handout had nothing. People reading a past handout see plain words
// instead. The stored data is untouched (the faculty quality checks still look for the marker).

export const IMPORTER_PLACEHOLDER = /\(missing — placeholder generated by importer\)/g;
export const NOT_IN_OLD_FILE = 'Not found in the old handout file';

export const plainPlaceholderText = (s: string) => s.replace(IMPORTER_PLACEHOLDER, NOT_IN_OLD_FILE);

/** A copy of a past handout with every importer placeholder in plain words. */
export function withPlainPlaceholders<T>(value: T): T {
  if (typeof value === 'string') return plainPlaceholderText(value) as T;
  if (Array.isArray(value)) return value.map((v) => withPlainPlaceholders(v)) as T;
  if (value && typeof value === 'object' && !(value instanceof Date)) {
    return Object.fromEntries(
      Object.entries(value).map(([k, v]) => [k, withPlainPlaceholders(v)]),
    ) as T;
  }
  return value;
}
